// ===== WT-Score: Per-tool scoring =====
// Scores ONE tool. Takes the tool record + its linked vendor, computes
// integration/demand/outreach/priority scores on 0-100, assigns tier by
// absolute threshold, writes results back.
//
// Normalization: fixed log-scale caps (not per-category min/max) so each
// tool can be scored independently without the full population.

const tool = $('Get Tool Record').first().json;
const vendorItem = $input.first()?.json || {};

// Get Linked Vendor uses onError: continueRegularOutput. If that node errored
// (no vendor linked, bad id), the input item (the tool record) passes through.
// Detect real vendor data by the presence of vendor-only fields.
const hasVendor = !!(
  vendorItem && (
    vendorItem.company_name != null ||
    vendorItem.company_size != null ||
    vendorItem.funding_stage != null
  )
);
const vendor = hasVendor ? vendorItem : {};

// --- Fixed-cap log normalization ---
// value at/above `cap` → 100. Caps are realistic upper bounds for AEC tools.
function logNorm(value, cap) {
  const v = Math.log((Number(value) || 0) + 1);
  const max = Math.log(cap + 1);
  if (max <= 0) return 0;
  return Math.max(0, Math.min(100, (v / max) * 100));
}

function norm(value, min, max) {
  if (max <= min) return 50;
  const v = Number(value) || 0;
  return Math.max(0, Math.min(100, ((v - min) / (max - min)) * 100));
}

function bayesianRating(rating, count) {
  const m = 15; const C = 4.1;
  const v = count || 0; const R = rating || C;
  const wr = (v / (v + m)) * R + (m / (v + m)) * C;
  return (wr / 5) * 100;
}

function employeeSweetSpot(sizeStr) {
  const map = { '1-10': 20, '11-50': 50, '51-200': 100, '201-1000': 90, '1001-5000': 60, '5000+': 30 };
  return map[sizeStr] != null ? map[sizeStr] : 50;
}

function fundingScoreFn(stage) {
  const map = { 'Bootstrapped': 40, 'Pre-seed': 30, 'Seed': 50, 'Series A': 80, 'Series B': 90, 'Series C': 100, 'Series D+': 85, 'Public': 50, 'Acquired': 40, 'Unknown': 30 };
  return map[stage] != null ? map[stage] : 30;
}

function blogRecency(daysAgo) {
  if (daysAgo == null) return 30;
  if (daysAgo <= 7) return 100;
  if (daysAgo <= 30) return 80;
  if (daysAgo <= 90) return 60;
  if (daysAgo <= 180) return 40;
  if (daysAgo <= 365) return 20;
  return 10;
}

// --- Integration Score (0-100) — tool-level signals ---
const integrationScore =
  0.30 * logNorm(tool.marketplace_count, 4) +
  0.25 * (tool.has_api_docs ? 100 : 0) +
  0.20 * logNorm(tool.integration_count, 100) +
  0.15 * logNorm(tool.ipaas_count, 3) +
  0.10 * logNorm(tool.zapier_trigger_count, 50);

// --- Demand Score (0-100) — tool-level signals ---
const totalReviews = (Number(tool.g2_review_count) || 0) + (Number(tool.capterra_review_count) || 0);
const bestRating = Number(tool.g2_rating) || Number(tool.capterra_rating) || null;
const demandScore =
  0.30 * logNorm(totalReviews, 5000) +
  0.25 * bayesianRating(bestRating, totalReviews) +
  0.20 * logNorm(tool.search_volume_monthly, 100000) +
  0.15 * norm(tool.google_trends_index, 0, 100) +
  0.10 * logNorm(tool.reddit_mentions_24mo, 500);

// --- Outreach Score (0-100) — vendor-level signals ---
const outreachScore =
  0.30 * employeeSweetSpot(vendor.company_size) +
  0.25 * (vendor.has_partner_program ? 100 : 0) +
  0.20 * fundingScoreFn(vendor.funding_stage) +
  0.15 * logNorm(vendor.press_count_12mo, 50) +
  0.10 * blogRecency(vendor.blog_last_post_days_ago != null ? Number(vendor.blog_last_post_days_ago) : null);

// --- Priority Score ---
const priorityScore =
  0.40 * integrationScore +
  0.35 * demandScore +
  0.25 * outreachScore;

// --- Emerging flag ---
const currentYear = new Date().getFullYear();
const foundedYear = Number(vendor.founded_year) || 0;
const isYoung = foundedYear > (currentYear - 4);
const emergingFlag = !!(isYoung && tool.has_api_docs && (Number(tool.marketplace_count) || 0) >= 1);

// --- Tier by absolute threshold (scoring plan, §Tiering) ---
let priorityTier;
if (priorityScore >= 80) priorityTier = '1';
else if (priorityScore >= 55) priorityTier = '2';
else if (priorityScore >= 30) priorityTier = '3';
else priorityTier = '4';

// Emerging flag forces minimum Tier 2
if (emergingFlag && priorityTier > '2') priorityTier = '2';

return [{ json: {
  id: tool.id,
  integration_score: Math.round(integrationScore * 10) / 10,
  demand_score: Math.round(demandScore * 10) / 10,
  outreach_score: Math.round(outreachScore * 10) / 10,
  priority_score: Math.round(priorityScore * 10) / 10,
  priority_tier: priorityTier,
  emerging_flag: emergingFlag,
  last_scored_at: new Date().toISOString()
} }];

const scored = $('Compute Score').first().json;

return [{ json: {
  record_id: scored.id,
  workflow: 'WT-Score',
  status: 'success',
  priority_score: scored.priority_score,
  priority_tier: scored.priority_tier,
  emerging_flag: scored.emerging_flag,
  note: `Scored tool (tier ${scored.priority_tier}, score ${scored.priority_score})`
} }];
